select ok(not exists(select 1 from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname='transition_insurance_claim' and pg_get_function_identity_arguments(p.oid) in ('uuid, _status text, _amount_approved numeric, _amount_paid numeric, _rejection_reason text, _notes text, _to_status text','uuid, _to_status text, _notes text')),'legacy insurance claim transition overloads are removed');
select ok(has_function_privilege('authenticated','public.transition_insurance_claim_canonical(uuid,text,numeric,numeric,text,text)','EXECUTE') and not has_function_privilege('anon','public.transition_insurance_claim_canonical(uuid,text,numeric,numeric,text,text)','EXECUTE'),'canonical insurance claim transition remains authenticated-only');